mapper.select:
SELECT s.course_id, s.sec_id, s.semester, s.year, c.title AS courseTitle, s.building, s.room_number, s.time_slot_id, cl.capacity, (SELECT COUNT(*) FROM takes k WHERE k.course_id = s.course_id AND k.sec_id = s.sec_id AND k.semester = s.semester AND k.year = s.year) AS enrolled FROM section s JOIN course c ON s.course_id = c.course_id LEFT JOIN classroom cl ON s.building = cl.building AND s.room_number = cl.room_number
AND s.semester = #{semester}
AND s.year = #{year}
AND s.course_id = #{courseId}
ORDER BY s.year DESC, s.semester, s.course_id, s.sec_id
